The rollout controller below decides whether to roll back a new release. Here `flip(p)` returns true with probability p; `choice(xs, w)` picks one element of xs, element i with weight w[i] (equal weights if w is omitted); `observe(c)` discards the run unless c is true, so everything is conditioned on every observe statement that is reached holding. Each random call is independent of all others.
```javascript
let error_rate = "low";
let bad_build = flip(0.45);
if (bad_build) {
    error_rate = choice(["low", "elevated", "high"], [1, 4, 3]);
} else {
    error_rate = choice(["low", "elevated", "high"], [90, 15, 2]);
}
console.log("bad_build:", bad_build);
let checks_failed = 0;
for (let check = 0; check < 3; check++) {
    if (error_rate !== "low") {
        if (flip(0.6)) {
            checks_failed += 1;
        }
    } else {
        if (flip(0.1)) {
            checks_failed += 1;
        }
    }
}
console.log("error_rate:", error_rate);
let rolled_back = checks_failed >= 1;
```
